using FinanceInzicht.Application;using FinanceInzicht.Domain;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;using Minio;using Minio.DataModel.Args;
namespace FinanceInzicht.Infrastructure;
public static class Services{public static IServiceCollection AddInfrastructure(this IServiceCollection s,IConfiguration c){s.AddDbContext<AppDbContext>(o=>o.UseNpgsql(c.GetConnectionString("Postgres")));s.AddSingleton<IMinioClient>(_=>new MinioClient().WithEndpoint(c["ObjectStorage:Endpoint"]??"minio:9000").WithCredentials(c["ObjectStorage:AccessKey"]??"minioadmin",c["ObjectStorage:SecretKey"]??"minioadmin").WithSSL(bool.TryParse(c["ObjectStorage:Secure"],out var x)&&x).Build());s.AddSingleton<IObjectStorage,MinioStorage>();return s;}}
public sealed class MinioStorage(IMinioClient client,IConfiguration cfg):IObjectStorage{string Bucket=>cfg["ObjectStorage:Bucket"]??"camt-private";public async Task PutAsync(string k,Stream s,string t,CancellationToken ct)=>await client.PutObjectAsync(new PutObjectArgs().WithBucket(Bucket).WithObject(k).WithStreamData(s).WithObjectSize(s.Length).WithContentType(t),ct);public async Task<Stream> OpenReadAsync(string k,CancellationToken ct){var m=new MemoryStream();await client.GetObjectAsync(new GetObjectArgs().WithBucket(Bucket).WithObject(k).WithCallbackStream(x=>x.CopyTo(m)),ct);m.Position=0;return m;}public async Task<bool> ExistsAsync(string k,CancellationToken ct){try{await client.StatObjectAsync(new StatObjectArgs().WithBucket(Bucket).WithObject(k),ct);return true;}catch{return false;}}}
public sealed class JobStore(AppDbContext db){public async Task<ImportJob?> ClaimAsync(string worker,TimeSpan stale,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(ct);var job=await db.ImportJobs.FromSqlInterpolated($"SELECT * FROM import_jobs WHERE status = {(int)ImportStatus.Pending} OR (status = {(int)ImportStatus.Processing} AND started_at_utc < {DateTimeOffset.UtcNow-stale}) ORDER BY created_at_utc FOR UPDATE SKIP LOCKED LIMIT 1").Include(x=>x.ImportFile).FirstOrDefaultAsync(ct);if(job is null)return null;job.Status=ImportStatus.Processing;job.StartedAtUtc=DateTimeOffset.UtcNow;job.WorkerId=worker;job.AttemptCount++;await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return job;}}
